def forward(groups):
    speeds = []
    for g in groups:
        if g == '****':
            speeds.append(-1)
        else:
            speeds.append(int(g))
    return {'stored': speeds, 'layout': []}

def inverse(record):
    speeds = record['stored']
    return f"({ ' '.join(str(s) if s != -1 else '****' for s in speeds) })"
